import { FileText, Paperclip, Calendar } from 'lucide-react'

type FeedCardImage = {
  variant: 'image'
  thumbnail: string
  title: string
  excerpt?: string
}

type FeedCardText = {
  variant: 'text'
  title: string
  tags?: string[]
  body?: string
  fileCount?: number
  attachmentCount?: number
  date?: string
  accentColor?: 'yellow' | 'green' | 'purple'
}

type Props = (FeedCardImage | FeedCardText) & { onClick?: () => void; className?: string }

const ACCENT_CLASSES: Record<string, string> = {
  yellow: 'border-l-accent-yellow',
  green: 'border-l-accent-green',
  purple: 'border-l-accent-purple',
}

export function FeedCard(props: Props) {
  if (props.variant === 'image') {
    return (
      <button
        onClick={props.onClick}
        className={`w-full text-left flex gap-3 p-3 rounded-lg hover:bg-muted/50 transition-colors ${props.className ?? ''}`}
      >
        <img
          src={props.thumbnail}
          alt=""
          className="w-20 h-15 object-cover rounded-md flex-shrink-0"
          style={{ height: '60px' }}
        />
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium text-foreground line-clamp-2">{props.title}</p>
          {props.excerpt && (
            <p className="text-xs text-muted-foreground line-clamp-1 mt-1">{props.excerpt}</p>
          )}
        </div>
      </button>
    )
  }

  const accentClass = props.accentColor ? ACCENT_CLASSES[props.accentColor] : 'border-l-border'

  return (
    <button
      onClick={props.onClick}
      className={`w-full text-left border-l-4 pl-3 py-2 hover:bg-muted/30 rounded-r-lg transition-colors ${accentClass} ${props.className ?? ''}`}
    >
      <p className="text-sm font-medium text-foreground">{props.title}</p>
      {props.tags && props.tags.length > 0 && (
        <div className="flex flex-wrap gap-1 mt-1.5">
          {props.tags.map((tag) => (
            <span key={tag} className="px-1.5 py-0.5 text-xs bg-muted text-muted-foreground rounded">
              {tag}
            </span>
          ))}
        </div>
      )}
      {props.body && (
        <p className="text-xs text-muted-foreground mt-1.5 line-clamp-2">{props.body}</p>
      )}
      <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground">
        {props.fileCount !== undefined && (
          <span className="flex items-center gap-1"><FileText size={11} /> {props.fileCount}</span>
        )}
        {props.attachmentCount !== undefined && (
          <span className="flex items-center gap-1"><Paperclip size={11} /> {props.attachmentCount}</span>
        )}
        {props.date && (
          <span className="flex items-center gap-1"><Calendar size={11} /> {props.date}</span>
        )}
      </div>
    </button>
  )
}
